13: /** Hold a ledger's lock across the entire read/modify/write session. */
14: export function acquireLedgerLock(ledgerPath, { handleSignals = true } = {}) {
15:   const path = resolve(ledgerPath);
16:   mkdirSync(dirname(path), { recursive: true });
17:   const lockPath = join(realpathSync(dirname(path)), `${basename(path)}.lock`);
18:   let fd;
19:   try {
20:     fd = openSync(lockPath, 'wx', 0o600);
21:   } catch (error) {
22:     if (error.code === 'EEXIST') throw new LedgerLockedError(lockPath);
23:     throw error;
24:   }
25:   try {
26:     writeFileSync(fd, `${process.pid}\n`, 'utf8');
27:   } catch (error) {
28:     unlinkSync(lockPath);
29:     throw error;
30:   } finally {
31:     closeSync(fd);
32:   }
33: 
34:   let released = false;
35:   const onInterrupt = () => process.exit(130);
36:   const onTerminate = () => process.exit(143);
37:   const onHangup = () => process.exit(129);
38:   const release = () => {
39:     if (released) return;
40:     unlinkSync(lockPath);
41:     released = true;
42:     process.removeListener('exit', release);
43:     process.removeListener('SIGINT', onInterrupt);
44:     process.removeListener('SIGTERM', onTerminate);
