118: /**
119:  * Parses raw stdout from `agy models` into an array of model entries.
120:  *
121:  * @param {string} stdout
122:  * @returns {Array<{ slug: string, description: string }>}
123:  */
124: export function parseInstalledModels(stdout) {
125:   if (typeof stdout !== "string") {
126:     return [];
127:   }
128:   const lines = stdout.split(/\r?\n/);
129:   const models = [];
130:   for (const line of lines) {
131:     const trimmed = line.trim();
132:     if (!trimmed) continue;
133:     if (/^fetching\b/i.test(trimmed)) continue;
134:     // Slugs contain no whitespace. First non-whitespace sequence is the slug; the remainder is the description.
135:     const match = trimmed.match(/^(\S+)(?:\s+(.*))?$/);
136:     if (match) {
137:       models.push({
138:         slug: match[1],
139:         description: (match[2] || "").trim(),
140:       });
141:     }
142:   }
143:   return models;
144: }
