146: /**
147:  * Discovers installed models by querying `agy models` at runtime.
148:  *
149:  * @param {object} [opts]
150:  * @param {string} [opts.agyPath] - Path to agy executable (defaults to AGY_PATH env or "agy")
151:  * @param {number} [opts.timeout=15000] - Discovery timeout in ms
152:  * @param {object} [opts.env] - Additional environment variables
153:  * @param {string} [opts.cwd] - Working directory
154:  * @returns {Array<{ slug: string, description: string }>}
155:  */
156: export function listInstalledModels(opts = {}) {
157:   const agyPath = opts.agyPath || process.env.AGY_PATH || "agy";
158:   const timeout = typeof opts.timeout === "number" ? opts.timeout : 15000;
159: 
160:   const result = spawnSync(agyPath, ["models"], {
161:     timeout,
162:     env: { ...process.env, ...(opts.env || {}) },
163:     cwd: opts.cwd || process.cwd(),
164:     encoding: "utf-8",
165:     maxBuffer: 5 * 1024 * 1024,
166:   });
167: 
168:   if (result.error) {
169:     throw new Error(`Failed to list installed models: ${result.error.message}`);
170:   }
171:   if (result.status !== 0) {
172:     throw new Error(
173:       `Failed to list installed models (exit code ${result.status}): ${result.stderr || ""}`
174:     );
175:   }
176: 
177:   return parseInstalledModels(result.stdout || "");
178: }
