180: /**
181:  * Evaluates whether a candidate model entry satisfies a role policy specification.
182:  *
183:  * @param {object} policy - Role policy from ROLE_POLICY_TABLE
184:  * @param {string|{ slug: string, description?: string }} model
185:  * @returns {boolean}
186:  */
187: export function matchesPolicy(policy, model) {
188:   if (!policy || !model) return false;
189: 
190:   const slug = (typeof model === "string" ? model : model.slug || "").trim().toLowerCase();
191:   const desc = (typeof model === "object" && model && model.description ? model.description : "").trim().toLowerCase();
192: 
193:   const familySlug = policy.family.toLowerCase().replace(/[^a-z0-9.]+/g, "-");
194:   const familyText = policy.family.toLowerCase();
195:   const effort = policy.effort.toLowerCase();
196: 
197:   const familyMatch = slug.includes(familySlug) || (desc.length > 0 && desc.includes(familyText));
198:   if (!familyMatch) return false;
199: 
200:   const effortMatch =
201:     slug.endsWith(`-${effort}`) ||
202:     slug.includes(`-${effort}-`) ||
203:     (desc.length > 0 &&
204:       (desc.includes(`(${effort})`) || desc.includes(` ${effort} `) || desc.endsWith(` ${effort}`)));
205: 
206:   return effortMatch;
207: }
