209: /**
210:  * Resolves a role name to its exact AGY model slug against the installed AGY surface.
211:  * Case-insensitive. Throws structured UnresolvedModelSlugError if 0 matches, ambiguous matches,
212:  * or unknown role. No silent fallback.
213:  *
214:  * @param {string} role - Role name (e.g. 'piledriver', 'bulldozer', 'steamroller')
215:  * @param {object} [opts] - Resolution options
216:  * @param {Array<string|object>} [opts.installedModels] - Optional pre-fetched/cached model surface for deterministic testing
217:  * @param {string} [opts.agyPath] - Path to agy executable
218:  * @returns {string} Exact model slug
219:  */
220: export function resolveSlug(role, opts = {}) {
221:   const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
222:   const policy = ROLE_POLICY_TABLE[normalized];
223:   if (!ROLE_BODY_ROLES.includes(normalized)) {
224:     throw new UnresolvedModelSlugError(
225:       role,
226:       `Unknown role: "${role}". No role policy defined.`
227:     );
228:   }
229: 
230:   let installed = opts.installedModels;
231:   if (!installed) {
232:     try {
233:       installed = listInstalledModels(opts);
234:     } catch (err) {
235:       throw new UnresolvedModelSlugError(
236:         role,
237:         `Failed to discover installed models for role "${role}": ${err.message}`,
238:         { cause: err }
239:       );
240:     }
241:   }
242: 
243:   if (!Array.isArray(installed)) {
244:     installed = [installed];
245:   }
246: 
247:   const matches = installed.filter((m) => matchesPolicy(policy, m));
248:   if (matches.length === 0) {
249:     throw new UnresolvedModelSlugError(
250:       role,
251:       `No installed model found matching policy for role "${role}" (family: "${policy.family}", effort: "${policy.effort}").`,
252:       { reason: "NOT_FOUND" }
253:     );
254:   }
255: 
256:   if (matches.length > 1) {
257:     const candidateSlugs = matches.map((m) => (typeof m === "string" ? m : m.slug));
258:     throw new UnresolvedModelSlugError(
259:       role,
260:       `Ambiguous model slug resolution for role "${role}": multiple matching models found: ${candidateSlugs.join(", ")}`,
261:       { reason: "AMBIGUOUS", matches: candidateSlugs }
262:     );
263:   }
264: 
265:   const resolved = matches[0];
266:   return typeof resolved === "string" ? resolved : resolved.slug;
267: }
