283:   const FORBIDDEN_KEYS = ["messages", "conversation", "history", "transcript"];
284:   for (const forbidden of FORBIDDEN_KEYS) {
285:     if (forbidden in packet && packet[forbidden] !== undefined) {
286:       throw new InvalidHandoffPacketError(
287:         `Forbidden conversational state field in handoff packet: "${forbidden}". Raw conversational state is prohibited.`
288:       );
