299:   if (!task) {
300:     throw new InvalidHandoffPacketError(
301:       "Handoff packet requires a non-empty 'task' or 'objective' string"
302:     );
303:   }
304: 
305:   const sections = [];
306: 
307:   if (roleName) {
308:     sections.push(`## Role\n${roleName}`);
309:   }
310: 
311:   sections.push(`## Role Body\n${loadRoleBody(role, opts)}`);
312:   sections.push(`## Task\n${task}`);
313: 
314:   const contextFiles = packet.contextFiles ?? packet.context_files;
315:   if (contextFiles) {
316:     if (Array.isArray(contextFiles) && contextFiles.length > 0) {
317:       sections.push(`## Context Files\n${contextFiles.map((f) => `- ${f}`).join("\n")}`);
318:     } else if (typeof contextFiles === "string" && contextFiles.trim()) {
319:       sections.push(`## Context Files\n${contextFiles.trim()}`);
320:     }
321:   }
322: 
323:   const evidence = packet.evidence;
324:   if (evidence) {
325:     if (Array.isArray(evidence) && evidence.length > 0) {
326:       sections.push(`## Evidence\n${evidence.map((e) => `- ${e}`).join("\n")}`);
327:     } else if (typeof evidence === "string" && evidence.trim()) {
328:       sections.push(`## Evidence\n${evidence.trim()}`);
329:     } else if (typeof evidence === "object" && Object.keys(evidence).length > 0) {
330:       sections.push(`## Evidence\n${JSON.stringify(evidence, null, 2)}`);
331:     }
332:   }
333: 
334:   const constraints = packet.constraints;
335:   if (constraints) {
336:     if (Array.isArray(constraints) && constraints.length > 0) {
337:       sections.push(`## Constraints\n${constraints.map((c) => `- ${c}`).join("\n")}`);
338:     } else if (typeof constraints === "string" && constraints.trim()) {
339:       sections.push(`## Constraints\n${constraints.trim()}`);
340:     }
341:   }
342: 
343:   const expectedOutput = packet.expectedOutput ?? packet.expected_output;
344:   if (expectedOutput) {
345:     if (Array.isArray(expectedOutput) && expectedOutput.length > 0) {
346:       sections.push(`## Expected Output\n${expectedOutput.map((o) => `- ${o}`).join("\n")}`);
347:     } else if (typeof expectedOutput === "string" && expectedOutput.trim()) {
348:       sections.push(`## Expected Output\n${expectedOutput.trim()}`);
349:     }
350:   }
351: 
352:   return sections.join("\n\n");
353: }
