355: /**
356:  * Validates and parses the JSON response envelope from an AGY execution.
357:  * Only SUCCESS with valid string response and no explicit tool denials succeeds.
358:  * Denials return TOOL_PERMISSION_DENIED; other invalid envelopes return
359:  * structured INVALID_OUTPUT or MODEL_ERROR failure.
360:  *
361:  * @param {string} stdout - Raw stdout from agy
362:  * @param {object} [meta] - Context metadata (role, slug)
363:  * @returns {object} Structured result
364:  */
365: export function parseResponseEnvelope(stdout, meta = {}) {
366:   const role = meta.role;
367:   const slug = meta.slug;
368: 
369:   let parsed;
370:   try {
371:     parsed = JSON.parse(stdout.trim());
372:   } catch (parseErr) {
373:     return {
374:       ok: false,
375:       error: "INVALID_OUTPUT",
376:       ...(role ? { role } : {}),
377:       ...(slug ? { slug } : {}),
378:       message: `Failed to parse JSON response: ${parseErr.message}`,
379:       raw: stdout,
380:     };
381:   }
382: 
383:   if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
384:     return {
385:       ok: false,
386:       error: "INVALID_OUTPUT",
387:       ...(role ? { role } : {}),
388:       ...(slug ? { slug } : {}),
389:       message: "JSON response is not a valid object envelope",
390:       raw: parsed,
391:     };
392:   }
393: 
394:   if (parsed.status === "ERROR") {
395:     return {
396:       ok: false,
397:       error: "MODEL_ERROR",
398:       ...(role ? { role } : {}),
399:       ...(slug ? { slug } : {}),
400:       details: parsed,
401:     };
402:   }
403: 
404:   if (parsed.status === "SUCCESS") {
405:     if (Array.isArray(parsed.denied_actions) && parsed.denied_actions.length > 0) {
406:       return {
407:         ok: false,
408:         error: "TOOL_PERMISSION_DENIED",
409:         ...(role ? { role } : {}),
410:         ...(slug ? { slug } : {}),
411:         denied_actions: parsed.denied_actions,
412:         details: parsed,
413:       };
414:     }
415: 
416:     if (typeof parsed.response !== "string") {
417:       return {
418:         ok: false,
419:         error: "INVALID_OUTPUT",
420:         ...(role ? { role } : {}),
421:         ...(slug ? { slug } : {}),
422:         message: "Missing or invalid 'response' field in SUCCESS envelope",
423:         details: parsed,
424:       };
425:     }
426: 
427:     return {
428:       ok: true,
429:       ...(role ? { role } : {}),
430:       ...(slug ? { slug } : {}),
431:       response: parsed.response,
432:       duration: parsed.duration_seconds,
433:       usage: parsed.usage,
434:       raw: parsed,
435:     };
436:   }
437: 
438:   return {
439:     ok: false,
440:     error: "INVALID_OUTPUT",
441:     ...(role ? { role } : {}),
442:     ...(slug ? { slug } : {}),
443:     message: `Unexpected response status: "${parsed.status}"`,
444:     details: parsed,
445:   };
446: }
