448: /**
449:  * Validates the inner response when a caller requires a JSON object packet.
450:  * Generic text responses remain supported by the envelope/transport boundary.
451:  * Only narration/fences around one object may be removed. Role-specific schema
452:  * and authority checks remain at the spine/ledger boundary, after extraction.
453:  * response and raw are never rewritten: they retain the original provenance.
454:  */
455: export function parseResponsePacket(result) {
456:   if (!result.ok) return result;
457:   if (!result.response.trim()) return { ...result, ok: false, error: "EMPTY_RESPONSE" };
458:   let packet;
459:   try {
460:     packet = JSON.parse(result.response);
461:   } catch {
462:     const start = result.response.indexOf("{");
463:     const end = result.response.lastIndexOf("}");
464:     if (start === -1 || end < start) {
465:       return { ...result, ok: false, error: "INVALID_RESPONSE_FORMAT" };
466:     }
467:     // Do not search for a parsable subset or choose between successive packets.
468:     // Parsing first-to-last braces rejects multiple objects and malformed outer
469:     // objects, while JSON.parse handles nested objects and escaped string braces.
470:     const surrounding = result.response.slice(0, start) + "\n" + result.response.slice(end + 1);
471:     const narration = surrounding.replace(/^[ \t]*```(?:json)?[ \t]*$/gim, "");
472:     // Arrays, quoted JSON, unmatched delimiters and extra JSON scalar values
473:     // outside the candidate are not narration. Ambiguity must fail closed.
474:     if (/[{}\[\]"`]/.test(narration)
475:         || /(?:^|\s)(?:null|true|false|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)(?=\s|$)/.test(narration)) {
476:       return { ...result, ok: false, error: "INVALID_RESPONSE_FORMAT" };
477:     }
478:     try {
479:       packet = JSON.parse(result.response.slice(start, end + 1));
480:     } catch {
481:       return { ...result, ok: false, error: "INVALID_RESPONSE_FORMAT" };
482:     }
483:   }
484:   if (packet === null || typeof packet !== "object" || Array.isArray(packet)) {
485:     return { ...result, ok: false, error: "INVALID_RESPONSE_FORMAT" };
486:   }
487:   return { ...result, packet };
488: }
