504:   let slug;
505:   let prompt;
506:   let opts;
507: 
508:   if (typeof slugOrOpts === "object" && slugOrOpts !== null) {
509:     opts = slugOrOpts;
510:     slug = opts.slug;
511:     prompt = opts.prompt;
512:   } else {
513:     slug = slugOrOpts;
514:     prompt = maybePrompt;
515:     opts = maybeOpts || {};
516:   }
517: 
518:   const role = opts.role;
519:   const timeout = typeof opts.timeout === "number" ? opts.timeout : 90000;
520:   const outputFormat = opts.outputFormat || "json";
521:   const agyPath = opts.agyPath || process.env.AGY_PATH || "agy";
522: 
523:   // Recursion protection
524:   const chainRaw = process.env.NTG_RUNNER_CHAIN;
525:   if (role && chainRaw) {
526:     const normalizedRole = typeof role === "string" ? role.trim().toLowerCase() : String(role);
527:     const parts = chainRaw.split(":").map((s) => s.trim().toLowerCase()).filter(Boolean);
528:     if (parts.includes(normalizedRole)) {
529:       return {
530:         ok: false,
531:         error: "RECURSION_DETECTED",
532:         role,
533:         chain: chainRaw,
534:       };
535:     }
536:   }
537: 
538:   const nextChain = role ? (chainRaw ? `${chainRaw}:${role}` : role) : chainRaw;
539:   const childEnv = {
540:     ...process.env,
541:     ...(opts.env || {}),
542:     ...(nextChain ? { NTG_RUNNER_CHAIN: nextChain } : {}),
543:   };
544: 
545:   // The composed role body is the machine contract. Do not add --agent:
546:   // installed primary agents inject the released READY / PLAN READY contracts.
547:   const args = [
548:     "--model",
549:     slug,
550:     "--output-format",
551:     outputFormat,
552:   ];
553: 
554:   // Permission grant: owner decision 2026-10-07 — bulldozer may inspect
555:   // known execution context via tools (incl. RunCommand); discovery still
556:   // delegated. Skip-permissions applies to bulldozer invocations only.
557:   // Must precede --print: agy consumes the token after --print as the prompt.
558:   const normalizedRole = typeof role === "string" ? role.trim().toLowerCase() : "";
559:   if (normalizedRole === "bulldozer") {
560:     args.push("--dangerously-skip-permissions");
561:   }
562:   args.push("--print", prompt);
