564:   // Linux caps a single argv element at MAX_ARG_STRLEN (128 KiB); oversize
565:   // prompts would otherwise surface as an E2BIG SPAWN_ERROR that looks like
566:   // a broken agy install. Fail with a typed error before spawning (Refs #91).
567:   const promptBytes = Buffer.byteLength(typeof prompt === "string" ? prompt : String(prompt), "utf8");
568:   const MAX_ARG_STRLEN = 128 * 1024;
569:   if (promptBytes > MAX_ARG_STRLEN) {
570:     return {
571:       ok: false,
572:       error: "PROMPT_TOO_LARGE",
573:       ...(role ? { role } : {}),
574:       slug,
575:       promptBytes,
576:       limit: MAX_ARG_STRLEN,
577:     };
578:   }
